def unique_jobs(rows):
    seen = set()
    out = []
    for r in rows:
        sid = r.get('source_id')
        keep = False
        if sid is not None and sid != '':
            key = (r.get('source'), sid)
            if key not in seen:
                seen.add(key)
                keep = True
